<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Oidc\UserInvitation\Infrastructure\Driver\Rest;

use Psr\Http\Message\ResponseInterface;
use Psr\Http\Message\ServerRequestInterface;
use Civi\Lughauth\Features\Oidc\UserInvitation\Application\Usecase\Resend\InvitationResendUsecase;

class InvitationResendController
{
    public function __construct(
        private readonly InvitationResendUsecase $usecase,
    ) {
    }

    public function resend(ServerRequestInterface $_request, ResponseInterface $response, array $args): ResponseInterface
    {
        $uid    = $args['uid'];
        $tenant = $args['tenant'] ?? '';

        try {
            $this->usecase->resend($uid, $tenant);
            return $response->withStatus(204);
        } catch (\DomainException $e) {
            $body = json_encode(['error' => $e->getMessage()]);
            $response->getBody()->write($body !== false ? $body : '{}');
            return $response->withStatus(422)->withHeader('Content-Type', 'application/json');
        }
    }
}
